const ticket = $('Extraire contexte ticket').item.json;
const records = ($json.records || []);

const pieces_jointes = records.map(r => {
  const cd = r.ContentDocument || {};
  return cd.FileType ? `${cd.Title || 'fichier'}.${cd.FileType}` : (cd.Title || 'fichier');
});

return {
  json: {
    ...ticket,
    pieces_jointes,
    pieces_jointes_count: pieces_jointes.length
  }
};

